--liquibase formatted sql

--changeset rules:20261010090000-case-programs
-- Три программы кейса (п. 4.2) и правила п. 4.3 как данные программы (params.rules, ADR-027).
-- Демо-программа гипотезы PLT-00 больше не нужна.
insert into programs (code, version, name, demo, params, checklist, created_by, created_at)
select 'INNOVATION', 1, 'Инновационный проект', false,
       '{"rules": [{"code": "MIN_FIELDS", "title": "Минимум полей вычитан", "op": "REQUIRED_FIELDS", "severity": "WARNING", "fields": {"APPLICATION": ["orgName", "inn", "requestedAmount", "date"], "PD_CONSENT": ["fullName", "date"], "CERTIFICATE": ["number", "validUntil"], "PRESENTATION": ["projectName"], "COST_JUSTIFICATION": ["totalCost", "ownFunds"], "BANK_STATEMENT": ["orgName", "balance", "date"], "PROPERTY_DOC": ["cadastralNumber"], "GUARANTEE_LETTER": ["guarantorName", "amount", "date"], "GIMS_DECLARATION": ["number", "validUntil"]}}, {"code": "INN_FORMAT", "title": "ИНН — 10 или 12 цифр", "op": "PATTERN", "severity": "FAILED", "types": ["*"], "field": "inn", "normalize": "digits", "pattern": "\\d{10}|\\d{12}", "hint": "10 цифр у организации, 12 — у ИП"}, {"code": "INN_SAME", "title": "ИНН одинаков во всех документах", "op": "SAME_VALUE", "severity": "FAILED", "types": ["*"], "field": "inn", "includeApplicant": true}, {"code": "DATE_NOT_FUTURE", "title": "Дата документа не в будущем", "op": "DATE_NOT_FUTURE", "severity": "FAILED", "types": ["*"], "field": "date"}, {"code": "NOT_EXPIRED", "title": "Срок действия не истёк", "op": "NOT_EXPIRED", "severity": "FAILED", "types": ["CERTIFICATE", "GIMS_DECLARATION"], "field": "validUntil", "warnDays": 30}, {"code": "OWN_FUNDS_SHARE", "title": "Собственные средства не менее 50 % расходов", "op": "RATIO_MIN", "severity": "FAILED", "numerator": ["COST_JUSTIFICATION.ownFunds", "COST_JUSTIFICATION.totalCost - COST_JUSTIFICATION.requestedAmount", "APPLICATION.ownFunds", "COST_JUSTIFICATION.totalCost - APPLICATION.requestedAmount", "APPLICATION.totalCost - APPLICATION.requestedAmount"], "denominator": ["COST_JUSTIFICATION.totalCost", "APPLICATION.totalCost"], "min": "0.50"}, {"code": "REQUEST_MATCH", "title": "Сумма в заявлении совпадает с обоснованием затрат", "op": "EQUAL_SUM", "severity": "FAILED", "pairs": [{"left": "APPLICATION.requestedAmount", "right": "COST_JUSTIFICATION.requestedAmount"}, {"left": "APPLICATION.requestedAmount", "right": "COST_JUSTIFICATION.totalCost - COST_JUSTIFICATION.ownFunds"}, {"left": "APPLICATION.totalCost", "right": "COST_JUSTIFICATION.totalCost"}]}, {"code": "CADASTRAL_FORMAT", "title": "Кадастровый номер в принятом формате", "op": "PATTERN", "severity": "FAILED", "types": ["PROPERTY_DOC"], "field": "cadastralNumber", "normalize": "compact", "pattern": "\\d{2}:\\d{2}:\\d{6,7}:\\d+", "hint": "АА:ВВ:ССССССС:КК, например 61:44:0050706:12"}, {"code": "PRESENTATION_NOT_EMPTY", "title": "Презентация не пустая", "op": "NOT_EMPTY", "severity": "FAILED", "types": ["PRESENTATION"], "fields": ["projectName", "description"]}]}'::jsonb,
       '[{"item": "APPLICATION", "title": "Заявление на субсидию", "kind": "REQUIRED", "types": ["APPLICATION"], "single": true}, {"item": "CONSENT", "title": "Согласие на обработку персональных данных", "kind": "REQUIRED", "types": ["PD_CONSENT"], "single": false}, {"item": "PRESENTATION", "title": "Презентация проекта", "kind": "REQUIRED", "types": ["PRESENTATION"], "single": true}, {"item": "COSTS", "title": "Обоснование затрат", "kind": "REQUIRED", "types": ["COST_JUSTIFICATION"], "single": true}, {"item": "BANK", "title": "Выписка из банка", "kind": "REQUIRED", "types": ["BANK_STATEMENT"], "single": false}, {"item": "GUARANTEE", "title": "Гарантийное письмо", "kind": "REQUIRED", "types": ["GUARANTEE_LETTER"], "single": false}, {"item": "CERTIFICATE", "title": "Сертификат соответствия", "kind": "CONDITIONAL", "types": ["CERTIFICATE"], "single": false, "conditionText": "если продукция проекта подлежит сертификации"}]'::jsonb,
       'system', now()
where not exists (select 1 from programs where code = 'INNOVATION');
