       '[{"item": "APPLICATION", "title": "Заявление на субсидию", "kind": "REQUIRED", "types": ["APPLICATION"], "single": true}, {"item": "CONSENT", "title": "Согласие на обработку персональных данных", "kind": "REQUIRED", "types": ["PD_CONSENT"], "single": false}, {"item": "COSTS", "title": "Обоснование затрат", "kind": "REQUIRED", "types": ["COST_JUSTIFICATION"], "single": true}, {"item": "BANK", "title": "Выписка из банка", "kind": "REQUIRED", "types": ["BANK_STATEMENT"], "single": false}, {"item": "PROPERTY", "title": "Документ на недвижимое имущество", "kind": "REQUIRED", "types": ["PROPERTY_DOC"], "single": false}, {"item": "GIMS", "title": "Декларация ГИМС", "kind": "CONDITIONAL", "types": ["GIMS_DECLARATION"], "single": false, "conditionText": "если пляж используется для купания и подлежит освидетельствованию ГИМС"}]'::jsonb,
       'system', now()
where not exists (select 1 from programs where code = 'BEACH');
